WITH base AS (SELECT id, promo_code, discount_pct, LAST_DAY(ends_on) AS ends_on_month_end, COALESCE(channel, 'DIRECT') AS resolved_channel FROM promotions WHERE starts_on >= DATE '2024-03-13' AND discount_pct <= 0.3), metrics AS (SELECT *, CUME_DIST() OVER (PARTITION BY promo_code ORDER BY discount_pct) AS discount_pct_cume_dist, LEAD(discount_pct, 2) OVER (PARTITION BY promo_code ORDER BY ends_on_month_end, id) AS next_discount_pct FROM base), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on_month_end, id) AS latest_rank FROM metrics QUALIFY latest_rank = 1), scored AS (SELECT *, SUM(next_discount_pct) OVER w_recent AS cumulative_next_discount_pct, DENSE_RANK() OVER w_running AS next_discount_pct_dense_rank, AVG(next_discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on_month_end, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS next_discount_pct_avg_3 FROM ranked WINDOW w_recent AS (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (ORDER BY next_discount_pct DESC)), with_windows AS (SELECT *, AVG(cumulative_next_discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on_month_end, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS cumulative_next_discount_pct_avg_6_prior, FIRST_VALUE(cumulative_next_discount_pct, TRUE) OVER (PARTITION BY promo_code ORDER BY ends_on_month_end, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cumulative_next_discount_pct, PERCENT_RANK() OVER (ORDER BY discount_pct_cume_dist DESC) AS discount_pct_cume_dist_percent_rank, MAX(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_max_discount_pct, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY next_discount_pct_dense_rank DESC, id) AS row_seq FROM scored) SELECT id, promo_code, ends_on_month_end, discount_pct_cume_dist, next_discount_pct, latest_rank, cumulative_next_discount_pct, next_discount_pct_avg_3, cumulative_next_discount_pct_avg_6_prior, CASE WHEN promo_code RLIKE '^(SPRING10|WELCOME5)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS promo_code_zone FROM with_windows ORDER BY discount_pct_cume_dist DESC NULLS FIRST
